-- =====================================================================================================================================
-- four_mock_clients_seed.sql  -  INSERT-ONLY seed of version 2 for the four EXISTING mock clients. NOT EXECUTED. For review.
--
-- WARNING  Run only after (a) the target project is confirmed (it may be labelled PRODUCTION) and (b) explicit approval. Synthetic / mock test data only:
--          no secrets, no personal data, no legal determinations. role_access_matrix is not touched. No table, column or index is created.
-- KEEPS    the four client_configs rows (not inserted, checked), every version 1 draft row, and CLIENT_DUBAI's two stored holidays (checked, not inserted).
-- INSERTS  231 rows:
--   client_config_versions           4   CANADA=1  DUBAI=1  INDIA=1  USA=1
--   task_templates                  83   CANADA=19  DUBAI=26  INDIA=18  USA=20
--   client_document_requirements    61   CANADA=16  DUBAI=16  INDIA=16  USA=13
--   client_service_policies         71   CANADA=16  DUBAI=22  INDIA=16  USA=17
--   client_milestone_templates       4   CANADA=1  DUBAI=1  INDIA=1  USA=1
--   client_holidays                  8   CANADA=3  DUBAI=0  INDIA=2  USA=3
-- SAFETY   one transaction; guards abort if the state differs from the read-only dry run; every INSERT has a NOT EXISTS natural-key guard; the final
--          assertions abort (rolling everything back) if any row was skipped, any reference is wrong or any hash differs. No UPDATE/DELETE/ON CONFLICT.
-- =====================================================================================================================================
BEGIN;
LOCK TABLE public.client_document_requirements, public.client_service_policies, public.client_milestone_templates IN SHARE ROW EXCLUSIVE MODE;

DO $guard$
BEGIN
  IF (SELECT count(*) FROM (VALUES
    ('CLIENT_CANADA', 'America/Toronto', ARRAY[1,2,3,4,5]::integer[]),
    ('CLIENT_DUBAI', 'Asia/Dubai', ARRAY[1,2,3,4,5]::integer[]),
    ('CLIENT_INDIA', 'Asia/Kolkata', ARRAY[1,2,3,4,5,6]::integer[]),
    ('CLIENT_USA', 'America/New_York', ARRAY[1,2,3,4,5]::integer[])
  ) AS e(client_id, tz, wd) JOIN public.client_configs c ON c.client_id = e.client_id
      WHERE c.timezone = e.tz AND c.working_days = e.wd AND c.is_active AND c.settings_payload ->> 'environment' = 'mock') <> 4 THEN
    RAISE EXCEPTION 'the four client master rows are missing or differ from the profiles; nothing was written';
  END IF;
  IF EXISTS (SELECT 1 FROM public.client_config_versions WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA') AND version = 2)
     OR EXISTS (SELECT 1 FROM public.task_templates WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA'))
     OR EXISTS (SELECT 1 FROM public.client_document_requirements WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA'))
     OR EXISTS (SELECT 1 FROM public.client_service_policies WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA'))
     OR EXISTS (SELECT 1 FROM public.client_milestone_templates WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA')) THEN
    RAISE EXCEPTION 'version 2 or configuration rows already exist for these clients; this is a first-time seed; nothing was written';
  END IF;
  IF (SELECT count(*) FROM (VALUES
    ('CLIENT_DUBAI', '2026-12-02'::date, '[SAMPLE] UAE National Day', TRUE),
    ('CLIENT_DUBAI', '2026-12-03'::date, '[SAMPLE] UAE National Day (2nd)', TRUE)
  ) AS e(client_id, holiday_date, name, observed) JOIN public.client_holidays h ON h.client_id = e.client_id AND h.holiday_date = e.holiday_date
      AND h.name = e.name AND h.is_observed = e.observed) <> 2 THEN
    RAISE EXCEPTION 'the preserved stored holidays differ from the profiles; nothing was written';
  END IF;
END
$guard$;

