DO $verify$
DECLARE bad text;
BEGIN
  SELECT string_agg(e.tbl || '/' || e.client || ': expected ' || e.expected || ' found ' || a.n, '; ') INTO bad
  FROM (VALUES
      ('client_config_versions', 'CLIENT_CANADA', 1),
      ('client_config_versions', 'CLIENT_DUBAI', 1),
      ('client_config_versions', 'CLIENT_INDIA', 1),
      ('client_config_versions', 'CLIENT_USA', 1),
      ('task_templates', 'CLIENT_CANADA', 19),
      ('task_templates', 'CLIENT_DUBAI', 26),
      ('task_templates', 'CLIENT_INDIA', 18),
      ('task_templates', 'CLIENT_USA', 20),
      ('client_document_requirements', 'CLIENT_CANADA', 16),
      ('client_document_requirements', 'CLIENT_DUBAI', 16),
      ('client_document_requirements', 'CLIENT_INDIA', 16),
      ('client_document_requirements', 'CLIENT_USA', 13),
      ('client_service_policies', 'CLIENT_CANADA', 16),
      ('client_service_policies', 'CLIENT_DUBAI', 22),
      ('client_service_policies', 'CLIENT_INDIA', 16),
      ('client_service_policies', 'CLIENT_USA', 17),
      ('client_milestone_templates', 'CLIENT_CANADA', 1),
      ('client_milestone_templates', 'CLIENT_DUBAI', 1),
      ('client_milestone_templates', 'CLIENT_INDIA', 1),
      ('client_milestone_templates', 'CLIENT_USA', 1),
      ('client_holidays', 'CLIENT_CANADA', 3),
      ('client_holidays', 'CLIENT_DUBAI', 2),
      ('client_holidays', 'CLIENT_INDIA', 2),
      ('client_holidays', 'CLIENT_USA', 3)
  ) AS e(tbl, client, expected)
  JOIN LATERAL (SELECT CASE e.tbl
      WHEN 'client_config_versions' THEN (SELECT count(*) FROM public.client_config_versions WHERE client_id = e.client AND version = 2)
      WHEN 'task_templates' THEN (SELECT count(*) FROM public.task_templates WHERE client_id = e.client AND config_version = 2)
      WHEN 'client_document_requirements' THEN (SELECT count(*) FROM public.client_document_requirements WHERE client_id = e.client AND config_version = 2)
      WHEN 'client_service_policies' THEN (SELECT count(*) FROM public.client_service_policies WHERE client_id = e.client AND config_version = 2)
      WHEN 'client_milestone_templates' THEN (SELECT count(*) FROM public.client_milestone_templates WHERE client_id = e.client AND config_version = 2)
      WHEN 'client_holidays' THEN (SELECT count(*) FROM public.client_holidays WHERE client_id = e.client)
    END AS n) a ON TRUE
  WHERE a.n <> e.expected;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'row count mismatch: %', bad; END IF;

  SELECT string_agg(e.client, ', ') INTO bad FROM (VALUES
    ('CLIENT_CANADA', 'sha256:34983038da0a70bf8c9294bbea7006cc7a7bf150d7832392a26403e2de3f3a9e', 'sha256:71d5fb75f676aab30265df9f8042c58efc6e0861a836d5241dbe5b8436ea9797'),
    ('CLIENT_DUBAI', 'sha256:b19526ebbea7db3b1ebcf2e66d04cc540a133eaf233608cf1eebb7872797f330', 'sha256:1d5aec05a218e8b1927ebec92e16b07c957fcce2ea730c3b4adc336943fea2ee'),
    ('CLIENT_INDIA', 'sha256:d280c8935596201ffc08623be9787ea2d96838f1ce25ea36a44b05ab4a44839f', 'sha256:343629f75322a7b1a34332cce15864ecda97f4eb242918f8769d8b978ecf6d95'),
    ('CLIENT_USA', 'sha256:73dbee06cae671d0cae639c2e24200cfcb875f944219bd88b105a2d6a663d2c4', 'sha256:a79cb742c43c0e6fdaf3b67c91a988559273d4b7ba202abf461c4433e98b4485')
  ) AS e(client, doc_hash, sec_hash)
  WHERE (SELECT config_hash FROM public.client_config_versions WHERE client_id = e.client AND version = 2) IS DISTINCT FROM e.doc_hash
     OR (SELECT count(DISTINCT policy_details ->> 'sections_hash') FROM public.client_service_policies
         WHERE client_id = e.client AND config_version = 2 AND service_category = 'cfg_section') <> 1
     OR (SELECT min(policy_details ->> 'sections_hash') FROM public.client_service_policies
         WHERE client_id = e.client AND config_version = 2 AND service_category = 'cfg_section') IS DISTINCT FROM e.sec_hash;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'document or sections hash mismatch for: %', bad; END IF;

  SELECT string_agg(t.client_id || ':' || t.template_key || '->' || d, '; ') INTO bad
  FROM public.task_templates t, unnest(t.depends_on_template_keys) AS d
  WHERE t.client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA') AND NOT EXISTS (SELECT 1 FROM public.task_templates x WHERE x.client_id = t.client_id AND x.template_key = d);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'unknown dependency: %', bad; END IF;
  SELECT string_agg(m.client_id || ':' || k, '; ') INTO bad
  FROM public.client_milestone_templates m, unnest(m.required_task_keys) AS k
  WHERE m.client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA') AND NOT EXISTS (SELECT 1 FROM public.task_templates x WHERE x.client_id = m.client_id AND x.template_key = k);
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'milestone requires an unknown task: %', bad; END IF;

  IF EXISTS (SELECT 1 FROM public.client_service_policies WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA') GROUP BY client_id, config_version, service_category, service_key HAVING count(*) > 1)
     OR EXISTS (SELECT 1 FROM public.client_document_requirements WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA') GROUP BY client_id, config_version, requirement_key HAVING count(*) > 1)
  THEN RAISE EXCEPTION 'duplicate natural key'; END IF;
  IF (SELECT count(*) FROM public.client_config_versions WHERE client_id IN ('CLIENT_CANADA', 'CLIENT_DUBAI', 'CLIENT_INDIA', 'CLIENT_USA') AND version = 1 AND status = 'draft') <> 4 THEN
    RAISE EXCEPTION 'a version 1 draft row changed or is missing';
  END IF;
  RAISE NOTICE 'seed verified: 231 rows, version 2 for 4 existing mock clients; existing rows preserved';
END
$verify$;

COMMIT;
